components.css:
.ds-button { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; color: var(--ink, #202b45); }
.ds-button { cursor: pointer; } .ds-button:disabled { cursor: not-allowed; } .ds-button svg { flex-shrink: 0; }
.ds-button { display: inline-flex; align-items: center; justify-content: center; gap: 12px; min-height: 52px; padding: 14px 27px; border: 1px solid transparent; border-radius: 999px; font-size: 15px; font-weight: 500; text-decoration: none; transition: background .18s, transform .18s; }
.ds-primary { background: var(--blue, #304fc5); color: white; }
.ds-primary:hover:not(:disabled) { background: var(--blue-dark, #233b9b); transform: translateY(-2px); }
.ds-primary:active:not(:disabled) { transform: translateY(0); }
.ds-primary:disabled { color: #526178; background: #d7ddeb; }
.ds-button:focus-visible { outline: 2px solid var(--blue, #304fc5); outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-button { animation: none !important; transition: none !important; } }

.ds-text-button { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; color: var(--ink, #202b45); }
.ds-text-button { cursor: pointer; } .ds-text-button:disabled { cursor: not-allowed; } .ds-text-button svg { flex-shrink: 0; }
.ds-text-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 0; background: none; color: var(--muted, #657087); font-size: 14px; min-height: 44px; padding: 8px 0; }
.ds-text-button:hover:not(:disabled) { color: var(--blue, #304fc5); }
.ds-text-button:disabled { opacity: .45; }
.ds-text-button svg { width: 18px; height: 18px; }
.ds-text-button:focus-visible { outline: 2px solid var(--blue, #304fc5); outline-offset: 5px; }

.ds-answer-option { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; color: var(--ink, #202b45); }
.ds-answer-option svg { flex-shrink: 0; }
.ds-answer-option { display: flex; align-items: center; position: relative; gap: 16px; padding: 17px 20px; min-height: 68px; border: 1px solid var(--line, #dbe0e9); border-radius: 12px; background: #ffffff80; font-size: 14px; line-height: 1.8; cursor: pointer; transition: border-color .18s, background .18s; }
.ds-answer-option:hover { border-color: #91a4dd; }
.ds-answer-option:has(input:checked) { border-color: var(--blue, #304fc5); background: var(--blue-pale, #eaf0ff); color: var(--blue-dark, #233b9b); }
.ds-answer-option:focus-within { outline: 2px solid var(--blue, #304fc5); outline-offset: 3px; }
.ds-answer-option input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.ds-option-letter { display: grid; place-items: center; width: 29px; height: 29px; border: 1px solid var(--line, #dbe0e9); border-radius: 50%; flex-shrink: 0; font-size: 12px; color: var(--muted, #657087); }
.ds-answer-option:has(input:checked) .ds-option-letter { background: var(--blue, #304fc5); color: white; border-color: var(--blue, #304fc5); }
.ds-option-check { margin-left: auto; visibility: hidden; }
.ds-answer-option:has(input:checked) .ds-option-check { visibility: visible; }
@media (max-width: 767px) { .ds-answer-option { min-height: 71px; padding: 14px; gap: 11px; font-size: 13px; } .ds-option-letter { width: 26px; height: 26px; font-size: 11px; } .ds-option-check { width: 17px; } }
@media (prefers-reduced-motion: reduce) { .ds-answer-option { animation: none !important; transition: none !important; } }

.ds-page-navigation { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; color: var(--ink, #202b45); }
.ds-page-navigation a { color: inherit; text-underline-offset: 5px; touch-action: manipulation; }
.ds-page-navigation { display: flex; gap: 32px; margin-left: auto; }
.ds-page-navigation a { font-size: 14px; text-decoration: none; padding-block: 12px; }
.ds-page-navigation a:hover { color: var(--blue, #304fc5); }
@media (max-width: 767px) { .ds-page-navigation { display: none; } }
.ds-page-navigation a:focus-visible { outline: 2px solid var(--blue, #304fc5); outline-offset: 5px; }

.ds-collectible-card { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; color: var(--ink, #202b45); }
:where(.ds-collectible-card) :where(h2, p) { margin: 0; } .ds-collectible-card p { line-height: 1.85; } .ds-collectible-card h2 { font-family: var(--serif, "Noto Serif SC Variable", "Songti SC", serif); font-weight: 600; text-wrap: balance; } .ds-collectible-card svg { flex-shrink: 0; }
.ds-collectible-card { position: relative; width: min(346px, calc(100% - 46px)); background: linear-gradient(135deg, #eff3fd, #f7f8f4 65%); padding: 25px 28px 20px; border-radius: 16px; box-shadow: 6px 22px 50px #263c751a; transform: rotate(-6deg); color: var(--blue, #304fc5); z-index: 1; margin-left: 14px; }
.ds-card-topline { display: flex; align-items: center; justify-content: space-between; font-size: 11px; }
.ds-card-topline svg { width: 19px; height: 19px; }
.ds-collectible-card .ds-star-mark { display: block; width: 240px; max-width: 100%; margin: 15px auto 7px; }
.ds-card-title { display: flex; justify-content: space-between; align-items: center; }
.ds-card-title h2 { font-size: 38px; line-height: 1.5; }
.ds-card-title > span { font-size: 25px; font-variant-numeric: tabular-nums; }
.ds-card-title small { font-size: 11px; padding-left: 4px; }
.ds-role-english { font-size: 10px; letter-spacing: .12em; }
.ds-card-quote { font-size: 13px; color: var(--ink, #202b45); margin-top: 17px; max-width: 24ch; min-height: 48px; }
.ds-card-traits { margin-top: 18px; padding-top: 14px; border-top: 1px solid #cdd5ea; font-size: 11px; }
.ds-sample-note { font-size: 10px; color: var(--muted, #657087); margin-top: 14px; }
@media (max-width: 1023px) { .ds-collectible-card { padding: 22px; width: calc(100% - 22px); margin-left: 0; } .ds-collectible-card .ds-star-mark { width: 200px; } }
@media (max-width: 767px) { .ds-collectible-card { width: calc(100% - 35px); padding: 22px 24px 17px; margin-left: 5px; } .ds-collectible-card .ds-star-mark { width: 207px; margin-top: 11px; } .ds-card-title h2 { font-size: 34px; } .ds-card-quote { margin-top: 14px; font-size: 12px; } .ds-card-traits { margin-top: 14px; font-size: 10px; } .ds-sample-note { margin-top: 10px; font-size: 9px; } }

.ds-catalog-item { font-family: "Microsoft YaHei", "PingFang SC", sans-serif; color: var(--ink, #202b45); }
.ds-catalog-item { cursor: pointer; } .ds-catalog-item svg { flex-shrink: 0; }
.ds-catalog-item { display: flex; flex-direction: column; align-items: center; position: relative; background: transparent; border: 1px solid transparent; border-radius: 12px; padding: 10px 6px 18px; color: var(--muted, #657087); transition: background .2s, border-color .2s; }
.ds-catalog-item .ds-star-mark { width: 80px; max-width: 100%; margin-bottom: 8px; }
.ds-catalog-name { color: var(--ink, #202b45); font-family: var(--serif, "Noto Serif SC Variable", "Songti SC", serif); font-size: 17px; font-weight: 600; }
.ds-catalog-trait { font-size: 11px; margin-top: 7px; }
.ds-catalog-item.ds-selected { background: var(--blue-pale, #eaf0ff); border-color: #c8d4f3; color: var(--blue, #304fc5); }
.ds-catalog-item.ds-selected .ds-catalog-name { color: var(--blue, #304fc5); }
.ds-catalog-item:hover { background: #eaf0ff99; }
.ds-catalog-indicator { position: absolute; right: 8px; top: 9px; opacity: 0; }
.ds-catalog-item:hover .ds-catalog-indicator, .ds-catalog-item.ds-selected .ds-catalog-indicator { opacity: 1; }
@media (max-width: 1023px) { .ds-catalog-item { padding-block: 12px 18px; } }
@media (max-width: 767px) { .ds-catalog-item { padding: 10px 2px 14px; } .ds-catalog-item .ds-star-mark { width: 66px; margin-bottom: 4px; } .ds-catalog-name { font-size: 15px; } .ds-catalog-trait { font-size: 9px; } .ds-catalog-indicator { top: 6px; right: 5px; } }
.ds-catalog-item:focus-visible { outline: 2px solid var(--blue, #304fc5); outline-offset: 5px; }
@media (prefers-reduced-motion: reduce) { .ds-catalog-item { animation: none !important; transition: none !important; } }

.ds-question-progress { display: block; appearance: none; border: 0; width: 100%; height: 3px; background: var(--line, #dbe0e9); color: var(--blue, #304fc5); margin-top: 12px; border-radius: 2px; overflow: hidden; }
.ds-question-progress::-webkit-progress-bar { background: var(--line, #dbe0e9); }
.ds-question-progress::-webkit-progress-value { background: var(--blue, #304fc5); }
.ds-question-progress::-moz-progress-bar { background: var(--blue, #304fc5); }
